&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
&lt;col style=&quot;width: 5.5555%;&quot;&gt;
