&lt;li&gt;&lt;a href=&quot;#_anatomía_de_las_tareas_clave&quot;&gt;Anatomía de las Tareas Clave&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_startollamab_el_lanzador&quot;&gt;startOllamaB` — El Lanzador&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_signinb_el_interactivo&quot;&gt;signInB` — El Interactivo&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_pullmodelb_lo_configurable&quot;&gt;pullModelB` — Lo configurable&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_statusollamaall_el_diagnóstico&quot;&gt;statusOllamaAll` — El Diagnóstico&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_cleanollamab_la_limpieza_que_preserva_la_identidad&quot;&gt;cleanOllamaB` — La Limpieza que Preserva la Identidad&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_flujo_de_trabajo_completo_de_cero_a_dos_sesiones&quot;&gt;Flujo de trabajo completo — De cero a dos sesiones&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_por_qué_no_hacer_un_verdadero_plugin_gradle&quot;&gt;¿Por qué no hacer un verdadero plugin Gradle ?&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_lecciones_aprendidas&quot;&gt;Lecciones aprendidas&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_conclusión&quot;&gt;Conclusión&lt;/a&gt;&lt;/li&gt;
