&lt;li&gt;&lt;a href=&quot;#_descarga_de_tor_y_su_firma&quot;&gt;Descarga de Tor y su firma&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_verificación_criptográfica_de_la_firma&quot;&gt;Verificación criptográfica de la firma&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_importar_la_clave_pública_del_proyecto_tor&quot;&gt;Importar la clave pública del proyecto Tor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_2_verificar_la_firma&quot;&gt;2. Verificar la firma&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_caso_práctico_firma_válida_pero_clave_no_certificada&quot;&gt;Caso práctico: firma válida pero clave no certificada&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
